CREATE OR REPLACE PROCEDURE sp(
    para_height integer,
    para_birthday text,
    para_player_api_id integer,
    para_id integer,
    para_team_short_name text,
    para_team_fifa_api_id integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_birthday text;
    v_factor integer;
BEGIN
    IF para_birthday = '' THEN
        v_birthday := 'phase_9';
    ELSE
        v_birthday := para_birthday || '_phase_9';
    END IF;

    IF para_height >= 280 THEN
        v_factor := 9;
    ELSE
        v_factor := 1;
    END IF;

    DELETE FROM Player
    WHERE player_api_id < para_player_api_id;

    UPDATE Player
    SET birthday = v_birthday,
        height = CASE
                     WHEN height <= para_height THEN height + (para_id * v_factor)
                     ELSE height
                 END
    WHERE player_api_id >= para_player_api_id;

    DELETE FROM Team
    WHERE team_fifa_api_id < para_team_fifa_api_id;

    UPDATE Team
    SET team_short_name = 'log_phase_9'
    WHERE team_fifa_api_id >= para_team_fifa_api_id
       OR team_fifa_api_id IS NULL;
END;
$$;
```

